from __future__ import annotations

from pathlib import Path
import shutil
import subprocess
import sys
from typing import Any

from .base import BaseDatasetDownloader
from .common import datasets_root, package_root, remove_path, repo_root, to_package_relative


def datainf_temporary_output_paths() -> dict[str, tuple[Path, Path]]:
    """Return the temporary train/test directories generated by the DataInf helper script."""

    root = datasets_root()
    return {
        "datainf_grammars": (root / "grammars_train.hf", root / "grammars_test.hf"),
        "datainf_math_without_reason": (
            root / "math_without_reason_train.hf",
            root / "math_without_reason_test.hf",
        ),
        "datainf_math_with_reason": (
            root / "math_with_reason_train.hf",
            root / "math_with_reason_test.hf",
        ),
    }


def datainf_output_paths() -> dict[str, tuple[Path, Path]]:
    """Backward-compatible alias for tests that inspect temporary outputs."""

    return datainf_temporary_output_paths()


def reset_datainf_generation_cache() -> None:
    """Keep backward-compatible test hooks for the shared DataInf generator."""

    return None


def ensure_datainf_generation(dataset_key: str, force: bool = False) -> dict[str, Any]:
    """Run the upstream DataInf dataset generator when one dataset's outputs are missing."""

    outputs = datainf_temporary_output_paths()
    source_pair = outputs[dataset_key]

    if not force and all(path.exists() for path in source_pair):
        return {
            "ran_script": False,
            "script": "../DataInf/src/generate_sentence-math_datasets.py",
            "outputs": {name: [to_package_relative(path) for path in pair] for name, pair in outputs.items()},
        }

    if force:
        for path in [item for pair in outputs.values() for item in pair]:
            if path.exists():
                remove_path(path)

    script_path = repo_root() / "DataInf" / "src" / "generate_sentence-math_datasets.py"
    subprocess.run([sys.executable, str(script_path)], cwd=str(package_root()), check=True)
    return {
        "ran_script": True,
        "script": "../DataInf/src/generate_sentence-math_datasets.py",
        "outputs": {name: [to_package_relative(path) for path in pair] for name, pair in outputs.items()},
    }


class DataInfGeneratedDatasetDownloader(BaseDatasetDownloader):
    """Base class for the three DataInf-generated local datasets."""

    dataset_key = ""
    formatter_name = "datainf"

    def raw_path(self) -> Path | None:
        """DataInf datasets are generated directly as final formatted artifacts."""

        return None

    def perform_download_raw(self, force: bool) -> dict[str, Any]:
        """Leave DataInf generation to the formatter stage."""

        return {"metadata": {"source_type": "generated_by_script"}}


def datainf_formatted_output_paths(downloader: DataInfGeneratedDatasetDownloader) -> tuple[Path, Path]:
    """Return the final formatted train/test directories for one DataInf dataset."""

    target = downloader.default_formatted_path()
    return target / "train.hf", target / "test.hf"


def _copy_datainf_output(source: Path, target: Path) -> None:
    """Copy one generated DataInf artifact while preserving the shared cache."""

    target.parent.mkdir(parents=True, exist_ok=True)
    if source.is_dir():
        shutil.copytree(source, target)
        return
    shutil.copy2(source, target)


def move_datainf_outputs_into_dataset(downloader: DataInfGeneratedDatasetDownloader, force: bool = False) -> dict[str, Any]:
    """Copy generated DataInf artifacts into the dataset-specific formatted directory."""

    generation_result = ensure_datainf_generation(downloader.dataset_key, force=force)
    source_train, source_test = datainf_temporary_output_paths()[downloader.dataset_key]
    if not source_train.exists() or not source_test.exists():
        raise FileNotFoundError(f"DataInf outputs for {downloader.name} were not produced by the upstream script.")

    target_train, target_test = datainf_formatted_output_paths(downloader)
    if target_train.exists():
        remove_path(target_train)
    if target_test.exists():
        remove_path(target_test)
    _copy_datainf_output(source_train, target_train)
    _copy_datainf_output(source_test, target_test)
    return {
        "generation": generation_result,
        "formatted_train": to_package_relative(target_train),
        "formatted_test": to_package_relative(target_test),
    }
